"""Пароли, токены, TOTP и шифрование секрета 2FA (ТЗ 13)."""

from __future__ import annotations

import secrets
import uuid
from datetime import datetime, timedelta, timezone

import jwt
import pyotp
from argon2 import PasswordHasher
from argon2.exceptions import VerifyMismatchError
from cryptography.fernet import Fernet, InvalidToken

from app.core.config import get_settings

_ph = PasswordHasher()

ROLES = ("admin", "analyst", "manager")


def hash_password(password: str) -> str:
    return _ph.hash(password)


def verify_password(password_hash: str, password: str) -> bool:
    try:
        return _ph.verify(password_hash, password)
    except VerifyMismatchError:
        return False


def _fernet() -> Fernet:
    key = get_settings().totp_encryption_key.encode()
    return Fernet(key if len(key) == 44 else Fernet._derive_key(key))  # noqa: SLF001


def encrypt_secret(secret: str) -> str:
    return _fernet().encrypt(secret.encode()).decode()


def decrypt_secret(token: str) -> str:
    try:
        return _fernet().decrypt(token.encode()).decode()
    except InvalidToken as exc:  # конфигурационная ошибка, а не данные пользователя
        raise ValueError("TOTP_ENCRYPTION_KEY не соответствует ключу шифрования") from exc


def new_totp_secret() -> str:
    return pyotp.random_base32()


def totp_code(secret: str, at: datetime | None = None) -> str:
    return pyotp.TOTP(secret).now()  # только для CLI/демо; сверка идёт в verify_totp


def verify_totp(secret: str, code: str, valid_window: int = 1) -> bool:
    return pyotp.TOTP(secret).verify(code, valid_window=valid_window)


def hash_backup_codes(codes: list[str]) -> str:
    return "|".join(hash_password(c) for c in codes)


def check_backup_code(codes_hash: str | None, code: str) -> bool:
    if not codes_hash:
        return False
    for stored in codes_hash.split("|"):
        try:
            if _ph.verify(stored, code):
                return True
        except VerifyMismatchError:
            continue
    return False


def issue_access_token(user_id: int, role: str, scope: str = "full") -> str:
    now = datetime.now(timezone.utc)
    ttl = get_settings().partial_auth_ttl_min if scope == "mfa_pending" else get_settings().access_token_ttl_min
    payload = {
        "sub": str(user_id),
        "role": role,
        "scope": scope,
        "iat": now,
        "exp": now + timedelta(minutes=ttl),
        "jti": str(uuid.uuid4()),
    }
    return jwt.encode(payload, get_settings().secret_key, algorithm="HS256")


def decode_token(token: str) -> dict:
    return jwt.decode(token, get_settings().secret_key, algorithms=["HS256"])


def new_jti() -> str:
    return str(uuid.uuid4())


def new_backup_codes(count: int = 8) -> list[str]:
    return [secrets.token_hex(4).upper() for _ in range(count)]

